#' Run the simulation
#'
#' @param parameters_list A named list of model parameters as generated by [get_parameters()]
#' @param population_data A named list representing the seeded population, as generated by
#'   [generate_population_data()]. By default (`NULL`) a new population is generated from
#'   `parameters_list`. The simulation is the same whether or not the population is provided.
#' @param state Optional simulation state from a previous run, as returned in the
#'   `state` element of the output list. When provided, the simulation resumes from
#'   this state. `simulation_time` controls the number of *additional* timesteps to
#'   run (not the absolute end time). With time-varying transmission, beta
#'   vectors are indexed by day from the start of the original run, so they must
#'   have a value for every day up to the end of the resumed run.
#'   `parameters_list$seed` must be `NULL` or the seed the saved run used. The
#'   resumed run needs the population the saved run used: pass the same
#'   `population_data`, or leave it `NULL` to rebuild the population from the
#'   population seed saved in the state, in which case the population parameters
#'   must not change. The random number streams continue from the state, so a
#'   run resumed from a state matches an uninterrupted run. Default is `NULL`
#'   (start fresh).
#'
#' @return A list with two elements:
#'   \describe{
#'     \item{result}{A data frame of simulation outputs with one row per
#'       timestep simulated in this call. When resuming, `timestep` counts from
#'       the start of the original run, so the results of successive calls can be
#'       joined with `rbind()`. The columns are described below.}
#'     \item{state}{The final simulation state, which can be passed to a subsequent
#'       call to resume the simulation. A list with elements `timesteps` (the
#'       number of timesteps simulated so far), `individual` (the state of the
#'       individual package's variables, events and base R's random number
#'       generator), `dqrng` (dqrng's random number state), `seed` (the seed of
#'       the run, drawn at random when `parameters_list$seed` is `NULL`) and
#'       `population_seed` (the seed that built the population, which is the
#'       same as `seed` unless a population built with another seed was passed
#'       in).}
#'   }
#'
#' The \code{result} data frame always contains the following columns:
#'   \itemize{
#'     \item \code{timestep}: The simulation timestep index.
#'     \item \code{S_count}: The number of individuals in the Susceptible
#'       disease state.
#'     \item \code{E_count}: The number of individuals in the Exposed (infected
#'       but not yet infectious) disease state.
#'     \item \code{I_count}: The number of individuals in the Infectious
#'       disease state.
#'     \item \code{I_mild_count}: The number of individuals in the mild Infectious
#'       disease state.
#'     \item \code{I_hosp_count}: The number of individuals in the severe Infectious
#'       disease state that require hospitalization.
#'     \item \code{R_count}: The number of individuals in the Recovered
#'       (immune) disease state.
#'     \item \code{D_count}: The number of individuals in the Death
#'      state.
#'     \item \code{E_new}: The number of individuals newly transitioning from
#'       Susceptible to Exposed (i.e. new infections) at each timestep.
#'   }
#'
#' When \code{endemic_or_epidemic = "endemic"}, an additional column is included:
#'   \itemize{
#'     \item \code{n_external_infections}: The number of susceptible individuals
#'       infected via the external/background infection source at each timestep.
#'   }
#'
#' When \code{render_diagnostics = TRUE}, additional diagnostic columns are
#' included:
#'   \itemize{
#'     \item \code{FOI_household}: The maximum force of infection from household
#'       contacts across all individuals at each timestep.
#'     \item \code{FOI_workplace}: The maximum force of infection from workplace
#'       contacts across all individuals at each timestep.
#'     \item \code{FOI_school}: The maximum force of infection from school
#'       contacts across all individuals at each timestep.
#'     \item \code{FOI_leisure}: The maximum force of infection from leisure
#'       setting contacts across all individuals at each timestep.
#'     \item \code{FOI_community}: The community-level force of infection
#'       (derived from global prevalence) at each timestep.
#'     \item \code{FOI_total}: The maximum total force of infection (sum across
#'       all settings) experienced by any individual at each timestep.
#'   }
#'
#' @family model
#' @export
run_simulation <- function(
  parameters_list,
  population_data = NULL,
  state = NULL
) {
  if (!("seed" %in% names(parameters_list))) {
    stop("parameters list must contain a variable called seed")
  }

  if (!is.null(state)) {
    state_elements <- c("timesteps", "individual", "dqrng", "seed", "population_seed")
    if (!is.list(state) || !all(state_elements %in% names(state))) {
      stop(
        "state must be the state element returned by run_simulation(), a list with elements ",
        paste(state_elements, collapse = ", ")
      )
    }
    if (round(parameters_list$simulation_time / parameters_list$dt) < 1) {
      stop("when resuming from a state, simulation_time must cover at least one timestep (dt)")
    }
  }

  # The run's seed also seeds the intervention coverage, so a resumed run must
  # use the seed of the saved run to get the same coverage again. A fresh run
  # with seed = NULL draws a seed so it can be saved:
  if (is.null(state)) {
    if (is.null(parameters_list$seed)) {
      parameters_list$seed <- sample.int(.Machine$integer.max, 1)
    }
  } else {
    if (!is.null(parameters_list$seed) && !isTRUE(parameters_list$seed == state$seed)) {
      stop(
        "parameters_list$seed (", parameters_list$seed, ") differs from the seed of the ",
        "saved run (", state$seed, "). Resume with the same seed or with seed = NULL"
      )
    }
    parameters_list$seed <- state$seed
  }

  # A resumed run overwrites the population's variables with the saved ones, so
  # it needs the population the saved run used. That is either a population
  # passed in that was built with the saved population seed, or a population
  # rebuilt from that seed:
  if (is.null(population_data)) {
    population_parameters <- parameters_list
    if (!is.null(state)) {
      population_parameters$seed <- state$population_seed
    }
    population_data <- generate_population_data(population_parameters)
  } else if (!is.null(state) && !isTRUE(population_data$seed == state$population_seed)) {
    stop(
      "population_data was built with seed ", population_data$seed, ", but the saved run used ",
      "a population built with seed ", state$population_seed, ". Resume with that population, ",
      "or with population_data = NULL to rebuild it"
    )
  }

  # simulation_loop() takes an absolute end timestep, so when resuming, run
  # simulation_time's worth of timesteps on from where the saved state ended:
  start_timestep <- if (is.null(state)) 0 else state$timesteps
  timesteps <- start_timestep + round(parameters_list$simulation_time / parameters_list$dt)

  # Time-varying betas are indexed by day counted from the start of the original
  # run, so they must have a value for every day up to the end of this call:
  if (isTRUE(parameters_list$time_varying_transmission_on)) {
    end_day <- timestep_to_day(timesteps, parameters_list$dt)
    beta_names <- c("beta_household", "beta_workplace", "beta_school", "beta_leisure", "beta_community")
    if (any(lengths(parameters_list[beta_names]) < end_day)) {
      stop(
        "when time_varying_transmission_on is TRUE, all setting-specific betas must have a value for every day up to day ",
        end_day,
        " (the end of this run, counting from the start of any run it resumes)"
      )
    }
  }

  # Determine intervention coverage and efficacy for this population. This also
  # sets up the random stream that the simulation continues (see
  # generate_intervention_data()), so the simulation is the same whether or not
  # the population was provided:
  intervention_data <- generate_intervention_data(parameters_list, population_data)

  # Generate the model variables:
  variables_list <- create_variables(parameters_list, population_data)

  # Generate the model events:
  events_list <- create_events(
    variables_list = variables_list,
    parameters_list = parameters_list
  )

  # Set up the model renderer:
  renderer <- individual::Render$new(timesteps)

  # Generate the model processes:
  processes_list <- create_processes(
    variables_list = variables_list,
    events_list = events_list,
    parameters_list = parameters_list,
    population_data = population_data,
    intervention_data = intervention_data,
    renderer = renderer
  )

  # individual only saves base R's RNG state, so continue dqrng's stream separately:
  if (!is.null(state)) {
    dqrng::dqrng_set_state(state$dqrng)
  }

  # Use individual::simulation_loop() to run the model for the specified number of timesteps
  individual_state <- individual::simulation_loop(
    variables = variables_list,
    events = unlist(events_list),
    processes = processes_list,
    timesteps = timesteps,
    state = state$individual,
    # Continue the saved RNG stream so a resumed run matches an uninterrupted one
    restore_random_state = TRUE
  )

  final_state <- list(
    timesteps = timesteps,
    individual = individual_state,
    dqrng = dqrng::dqrng_get_state(),
    seed = parameters_list$seed,
    population_seed = population_data$seed
  )

  # Only return the timesteps simulated in this call:
  result <- renderer$to_dataframe()
  result <- result[result$timestep > start_timestep, , drop = FALSE]
  rownames(result) <- NULL
  list(result = result, state = final_state)
}

#' Run helios simulations using table of parameter values
#'
#' @param parameters_table A data frame in which each row contains parameter values for helios model parameters (preferably in data.frame() format)
#' @param output_type A character string instructing the function to output the parameters, simulations, or both (default = simulations)
#'
#' @family model
#' @export
#'
run_simulations_from_table <- function(
  parameters_table,
  output_type = "simulations"
) {
  # Check that the parameters_table is a data.frame object:
  if (!is.data.frame(parameters_table)) {
    stop("Error: parameters_table is not a data.frame - please reformat")
  }

  # Check that all parameters in the parameter_table are present in the get_parameters() parameters_list:
  if (!all(names(parameters_table) %in% names(get_parameters()))) {
    stop(
      "Error: Parameter name in parameter_table not a recognised helios parameter"
    )
  }

  # Convert the parameters_table to data.frame format:
  parameters_table <- as.data.frame(parameters_table)

  # Open a list to store the parameter lists:
  parameters_lists <- list()

  # Open a list to store the simulation outputs:
  simulation_outputs <- list()

  # TODO: Add lines to outputs that append the parameters varied to the dataframe:
  for (i in 1:nrow(parameters_table)) {
    # Open a new parameter list for the i-th row of the parameter table:
    parameters_lists[[i]] <- get_parameters()

    # For each column in the parameter table, overwrite the corresponding parameter in the list:
    for (j in 1:ncol(parameters_table)) {
      parameters_lists[[i]][[names(parameters_table[j])]] <- parameters_table[
        i,
        j
      ]
    }

    # Run the simulations if output_type is simulations or both:
    if (output_type %in% c("simulations", "both")) {
      # Run the simulation i-th simulation:
      simulation_outputs[[i]] <- run_simulation(
        parameters_list = parameters_lists[[i]]
      )$result

      # Append the varied parameters as columns:
      simulation_outputs[[i]] <- dplyr::bind_cols(
        simulation_outputs[[i]],
        dplyr::as_tibble(parameters_table[i, ])
      )

      # Print the simulation progress:
      print(paste0(
        "Simulation ",
        i,
        " complete (",
        (i / nrow(parameters_table) * 100),
        "% of simulations complete)"
      ))
    }
  }

  # Determine which objects to return:
  if (output_type == "parameters") {
    return(parameters_lists)
  } else if (output_type == "simulations") {
    return(simulation_outputs)
  } else if (output_type == "both") {
    return(list(parameters_lists, simulation_outputs))
  }
}
